public abstract record Either<TLeft, TRight>
{
    public sealed record Left(TLeft Reason) : Either<TLeft, TRight>;
    public sealed record Right(TRight Value) : Either<TLeft, TRight>;
}

static string Describe(Either<string, int> outcome) => outcome switch
{
    Either<string, int>.Left(var reason) => $"failed: {reason}",
    Either<string, int>.Right(var value) => $"ok: {value}",
    _ => throw new UnreachableException()   // keeps a new case from being swallowed
};

